package com.lmspilot.learning.api;
import com.fasterxml.jackson.databind.ObjectMapper; import com.lmspilot.learning.domain.*; import com.lmspilot.support.api.ApiException; import com.lmspilot.support.security.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
record SubmitAssignmentRequest(@NotNull UUID enrollmentId,@NotNull UUID courseId,String textAnswer,List<UUID> fileIds){} record GradeAssignmentRequest(@DecimalMin("0") @DecimalMax("100") Double score,String feedback,Boolean returnForRevision){} record AssignmentSubmissionResponse(UUID id,UUID enrollmentId,UUID courseId,UUID lessonId,UUID userId,int attemptNo,String textAnswer,List<UUID> fileIds,AssignmentSubmissionStatus status,Instant submittedAt,Double score,String feedback,UUID gradedBy,Instant gradedAt){}
@Service @Transactional class AssignmentSubmissionService {private final AssignmentSubmissionRepository repo;private final ObjectMapper mapper;AssignmentSubmissionService(AssignmentSubmissionRepository r,ObjectMapper m){repo=r;mapper=m;}List<AssignmentSubmissionResponse> mine(){return repo.findAllByUserIdOrderBySubmittedAtDesc(user()).stream().map(this::view).toList();}List<AssignmentSubmissionResponse> attempts(UUID enrollmentId,UUID lessonId){return repo.findAllByEnrollmentIdAndLessonIdOrderByAttemptNoDesc(enrollmentId,lessonId).stream().filter(e->e.userId.equals(user())).map(this::view).toList();}AssignmentSubmissionResponse submit(UUID lessonId,SubmitAssignmentRequest i,String key){if((i.textAnswer()==null||i.textAnswer().isBlank())&&(i.fileIds()==null||i.fileIds().isEmpty()))throw new ApiException(HttpStatus.BAD_REQUEST,"ASSIGNMENT_CONTENT_REQUIRED","Cần nhập nội dung hoặc đính kèm tệp");AssignmentSubmissionEntity e=new AssignmentSubmissionEntity();e.enrollmentId=i.enrollmentId();e.classId=i.courseId();e.courseId=i.courseId();e.lessonId=lessonId;e.userId=user();e.attemptNo=(int)repo.countByEnrollmentIdAndLessonId(i.enrollmentId(),lessonId)+1;e.textAnswer=i.textAnswer();try{e.fileIdsJson=mapper.writeValueAsString(i.fileIds()==null?List.of():i.fileIds());}catch(Exception ex){throw new ApiException(HttpStatus.BAD_REQUEST,"FILE_LIST_INVALID","Danh sách tệp không hợp lệ");}return view(repo.save(e));}List<AssignmentSubmissionResponse> queueByCourses(Set<UUID> ids){if(ids==null||ids.isEmpty())return List.of();return repo.findAllByCourseIdInAndStatusOrderBySubmittedAtAsc(ids,AssignmentSubmissionStatus.SUBMITTED).stream().map(this::view).toList();}AssignmentSubmissionResponse grade(UUID id,GradeAssignmentRequest i){AssignmentSubmissionEntity e=repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"SUBMISSION_NOT_FOUND","Không tìm thấy bài nộp"));e.score=i.score();e.feedback=i.feedback();e.gradedBy=user();e.gradedAt=Instant.now();e.updatedAt=e.gradedAt;e.status=Boolean.TRUE.equals(i.returnForRevision())?AssignmentSubmissionStatus.RETURNED:AssignmentSubmissionStatus.GRADED;return view(repo.save(e));}private AssignmentSubmissionResponse view(AssignmentSubmissionEntity e){List<UUID> files;try{files=Arrays.asList(mapper.readValue(e.fileIdsJson,UUID[].class));}catch(Exception x){files=List.of();}return new AssignmentSubmissionResponse(e.id,e.enrollmentId,e.courseId,e.lessonId,e.userId,e.attemptNo,e.textAnswer,files,e.status,e.submittedAt,e.score,e.feedback,e.gradedBy,e.gradedAt);}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}}}
@RestController @RequestMapping("/api/v1/learning/assignments") public class AssignmentSubmissionApi {private final AssignmentSubmissionService service;public AssignmentSubmissionApi(AssignmentSubmissionService s){service=s;}@GetMapping("/me") public List<AssignmentSubmissionResponse> mine(){return service.mine();}@GetMapping("/{lessonId}/attempts") public List<AssignmentSubmissionResponse> attempts(@PathVariable UUID lessonId,@RequestParam UUID enrollmentId){return service.attempts(enrollmentId,lessonId);}@PostMapping("/{lessonId}/submissions") @ResponseStatus(HttpStatus.CREATED) public AssignmentSubmissionResponse submit(@PathVariable UUID lessonId,@Valid @RequestBody SubmitAssignmentRequest i,@RequestHeader(value="Idempotency-Key",required=false)String key){return service.submit(lessonId,i,key);}@GetMapping("/queue-by-course") public List<AssignmentSubmissionResponse> queue(@RequestParam Set<UUID> courseId){return service.queueByCourses(courseId);}@PutMapping("/submissions/{id}/grade") public AssignmentSubmissionResponse grade(@PathVariable UUID id,@Valid @RequestBody GradeAssignmentRequest i){return service.grade(id,i);} }
